CREATE TABLE "users" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "full_name" varchar,
  "email" varchar UNIQUE NOT NULL,
  "password_hash" varchar NOT NULL,
  "created_at" timestamp
);

CREATE TABLE "airports" (
  "airport_code" varchar(3) PRIMARY KEY,
  "airport_name" varchar
);

CREATE TABLE "flights" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "traveller_id" integer,
  "origin" varchar(3),
  "destination" varchar(3),
  "departure" timestamp,
  "arrival" timestamp,
  "price" integer,
  "currency" varchar(3)
);

CREATE TABLE "flight_segments" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "flight_id" integer,
  "position" integer,
  "origin" varchar(3),
  "destination" varchar(3),
  "departure" timestamp,
  "arrival" timestamp,
  "airline" varchar,
  "flight_number" varchar,
  "aircraft" varchar
);

CREATE TABLE "invites" (
  "code" varchar PRIMARY KEY,
  "creator_id" integer,
  "expires_at" timestamp,
  "used_by" integer,
  "used_at" timestamp
);

CREATE TABLE "linked_trip_data" (
  "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "invite_code" varchar,
  "receiver_id" integer,
  "sender_id" integer,
  "payload" json,
  "created_at" timestamp
);

ALTER TABLE "flights" ADD FOREIGN KEY ("traveller_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "flights" ADD FOREIGN KEY ("origin") REFERENCES "airports" ("airport_code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "flights" ADD FOREIGN KEY ("destination") REFERENCES "airports" ("airport_code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "flight_segments" ADD FOREIGN KEY ("flight_id") REFERENCES "flights" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "flight_segments" ADD FOREIGN KEY ("origin") REFERENCES "airports" ("airport_code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "flight_segments" ADD FOREIGN KEY ("destination") REFERENCES "airports" ("airport_code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "invites" ADD FOREIGN KEY ("creator_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "invites" ADD FOREIGN KEY ("used_by") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "linked_trip_data" ADD FOREIGN KEY ("invite_code") REFERENCES "invites" ("code") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "linked_trip_data" ADD FOREIGN KEY ("receiver_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "linked_trip_data" ADD FOREIGN KEY ("sender_id") REFERENCES "users" ("id") DEFERRABLE INITIALLY IMMEDIATE;
